<?php require 'config.php'; require_login(); $uid=$_SESSION['uid'];
$chk=$pdo->prepare('SELECT is_admin FROM users WHERE id=?'); $chk->execute([$uid]); if (!$chk->fetchColumn()) { http_response_code(403); die('Admins only.'); }
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $a=$_POST['action'] ?? '';
  if ($a==='close') $pdo->prepare("UPDATE support SET status='closed' WHERE id=?")->execute([(int)$_POST['id']]);
  if ($a==='backup') { $out=[]; foreach (['users','accounts','transactions','recurring','budgets','goals','debts','assets','rules','tuition','support','audit_log'] as $t) $out[$t]=$pdo->query("SELECT * FROM $t")->fetchAll();
    foreach ($out['users'] as &$r) unset($r['password_hash'],$r['totp_secret']); unset($r); audit($pdo,$uid,'backup'); header('Content-Type: application/json'); header('Content-Disposition: attachment; filename=fintrack-backup-'.date('Ymd').'.json'); echo json_encode($out,JSON_UNESCAPED_UNICODE); exit; }
  header('Location: admin.php'); exit; }
$n=fn($sql)=>(int)$pdo->query($sql)->fetchColumn();
page_head('Admin'); ?><h1>Admin dashboard</h1>
<div class="grid"><div class="card stat"><span>Users</span><b><?= $n('SELECT COUNT(*) FROM users') ?></b></div><div class="card stat"><span>Premium</span><b><?= $n("SELECT COUNT(*) FROM users WHERE plan='premium'") ?></b></div><div class="card stat"><span>Transactions</span><b><?= $n('SELECT COUNT(*) FROM transactions') ?></b></div><div class="card stat"><span>Open tickets</span><b><?= $n("SELECT COUNT(*) FROM support WHERE status='open'") ?></b></div><div class="card stat"><span>Errors (7 days)</span><b><?= $n("SELECT COUNT(*) FROM app_log WHERE kind='error' AND at>DATE_SUB(NOW(),INTERVAL 7 DAY)") ?></b></div></div>
<form method="post" class="card"><?= csrf() ?><input type="hidden" name="action" value="backup"><button class="btn alt">Download backup (JSON)</button> <span class="note">Passwords and 2FA secrets are left out. For full automatic backups, schedule mysqldump (see README).</span></form>
<h2>Support &amp; feedback</h2><div class="card scroll"><table><tr><th>Date</th><th>User</th><th>Type</th><th>Subject / message</th><th></th></tr><?php foreach ($pdo->query("SELECT s.*,u.email FROM support s JOIN users u ON u.id=s.user_id ORDER BY s.status,s.id DESC LIMIT 30") as $r) echo '<tr><td>'.e($r['at']).'</td><td>'.e($r['email']).'</td><td>'.e($r['kind']).'</td><td><b>'.e($r['subject']).'</b><br>'.e($r['body']).'</td><td>'.($r['status']==='open'?'<form method="post">'.csrf().'<input type="hidden" name="action" value="close"><input type="hidden" name="id" value="'.$r['id'].'"><button class="link" style="color:var(--pri)">Close</button></form>':'closed').'</td></tr>'; ?></table></div>
<h2>Organisations &amp; universities</h2><div class="card scroll"><table><tr><th>Organisation</th><th class="r">Members</th><th class="r">Premium</th></tr><?php foreach ($pdo->query("SELECT org_name,COUNT(*) n,SUM(plan='premium') p FROM users WHERE org_name<>'' GROUP BY org_name ORDER BY n DESC") as $r) echo '<tr><td>'.e($r['org_name']).'</td><td class="r">'.$r['n'].'</td><td class="r">'.$r['p'].'</td></tr>'; ?></table></div>
<h2>Product analytics</h2><div class="card scroll"><table><tr><th>Page</th><th class="r">Sampled views</th><th class="r">Avg load (ms)</th></tr><?php foreach ($pdo->query("SELECT page,COUNT(*) n,AVG(ms) ms FROM app_log WHERE kind='page' AND at>DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY page ORDER BY n DESC LIMIT 15") as $r) echo '<tr><td>'.e($r['page']).'</td><td class="r">'.$r['n'].'</td><td class="r">'.round($r['ms']).'</td></tr>'; ?></table></div>
<h2>Recent errors</h2><div class="card scroll"><table><tr><th>When</th><th>File</th><th>Message</th></tr><?php foreach ($pdo->query("SELECT * FROM app_log WHERE kind='error' ORDER BY id DESC LIMIT 15") as $r) echo '<tr><td>'.e($r['at']).'</td><td>'.e($r['page']).'</td><td>'.e($r['detail']).'</td></tr>'; ?></table></div>
<h2>Audit log</h2><div class="card scroll"><table><tr><th>When</th><th>User</th><th>Action</th><th>Detail</th></tr><?php foreach ($pdo->query("SELECT * FROM audit_log ORDER BY id DESC LIMIT 20") as $r) echo '<tr><td>'.e($r['at']).'</td><td>'.e($r['user_id']).'</td><td>'.e($r['action']).'</td><td>'.e($r['detail']).'</td></tr>'; ?></table></div><?php page_foot();
